// product card factory
function productCard(d){
  const inst=COMP.ProductCard.createInstance();
  inst.findOne(n=>n.name==="Name").characters=d.name;
  const rr=inst.findOne(n=>n.name==="RatingRow");
  rr.findOne(n=>n.name==="Stars").remove();
  const st=makeStars(d.score,18);rr.insertChild(0,st);
  inst.findOne(n=>n.name==="Score").characters=d.score.toFixed(1)+"/5";
  inst.findOne(n=>n.name==="Price").characters=d.price;
  const old=inst.findOne(n=>n.name==="OldPrice");
  const disc=inst.findOne(n=>n.name==="Discount");
  if(d.old){old.characters=d.old;old.visible=true;disc.findOne(n=>n.name==="DiscountText").characters=d.disc;disc.visible=true;}
  else{old.visible=false;disc.visible=false;}
  const pf=inst.findOne(n=>n.name==="PhotoFrame");
  pf.findOne(n=>n.name==="Photo").remove();
  const ph=photo(d.photo,300);ph.name="Photo";pf.appendChild(ph);
  return inst;
}
