// product card factory using nested overrides
function productCard(d){
  const inst=COMP.ProductCard.createInstance();
  inst.findOne(n=>n.name==="Name").characters=d.name;
  const stars=inst.findOne(n=>n.name==="RatingRow").findOne(n=>n.name==="Stars");
  const kids=stars.children;
  const full=Math.floor(d.score),half=d.score%1>=0.5;
  for(let i=0;i<5;i++){
    const s=kids[i];
    if(i===full&&half){s.swapComponent(MEDIA["Icon_Star_Half"]);}
    const v=s.findOne(n=>n.type==="VECTOR"||n.type==="BOOLEAN_OPERATION");
    if(v)v.fills=solid(i<full||(i===full&&half)?C.star:C.starEmpty);
  }
  inst.findOne(n=>n.name==="Score").characters=d.score.toFixed(1)+"/5";
  inst.findOne(n=>n.name==="Price").characters=d.price;
  const old=inst.findOne(n=>n.name==="OldPrice");
  const disc=inst.findOne(n=>n.name==="Discount");
  if(d.old){old.characters=d.old;old.visible=true;disc.findOne(n=>n.name==="DiscountText").characters=d.disc;disc.visible=true;}
  else{old.visible=false;disc.visible=false;}
  const pf=inst.findOne(n=>n.name==="PhotoFrame");
  const ph=pf.findOne(n=>n.name==="Photo");
  ph.swapComponent(MEDIA[d.photo]);
  const r=ph.width/ph.height;ph.resize(300*r,300);
  return inst;
}
