function setStars(container,score,size){
  // container: Stars instance; rebuild children visibility by swapping
  const full=Math.floor(score);const half=score%1>=0.5;
  const kids=container.children;
  for(let i=0;i<5;i++){
    const s=kids[i];
    if(i<full){for(const v of s.children)v.fills=solid(AMBER);}
    else if(i===full&&half){/* replace with half */}
    else{for(const v of s.children)v.fills=solid({r:0.85,g:0.85,b:0.87});}
  }
  return {full,half};
}

async function productCard(data){
  const inst=C.ProductCard.createInstance();
  inst.name="ProductCard/"+data.name;
  const photo=inst.findOne(n=>n.name==="Photo");
  photo.fills=[{type:"IMAGE",imageHash:await hashOf(data.photoId),scaleMode:"FILL"}];
  inst.findOne(n=>n.name==="Name").characters=data.name;
  const stars=inst.findOne(n=>n.name==="Stars");
  const full=Math.floor(data.score);const half=data.score%1>=0.5;
  const kids=stars.children;
  for(let i=0;i<5;i++){
    if(i<full){for(const v of kids[i].children)v.fills=solid(AMBER);}
    else if(i===full&&half){
      const h=halfMain.createInstance();h.name="StarHalf";h.resize(18,18);for(const v of h.children)v.fills=solid(AMBER);
      stars.insertChild(i,h);kids[i+1].remove();
      // after insert, remaining shift; recolor rest gray below
      for(let j=i+1;j<stars.children.length;j++){const el=stars.children[j];if(el.name!=="StarHalf")for(const v of el.children)v.fills=solid({r:0.85,g:0.85,b:0.87});}
      break;
    }
    else{for(const v of kids[i].children)v.fills=solid({r:0.85,g:0.85,b:0.87});}
  }
  inst.findOne(n=>n.name==="Score").characters=data.score.toFixed(1)+"/5";
  inst.findOne(n=>n.name==="Price").characters=data.price;
  if(data.old){const o=inst.findOne(n=>n.name==="OldPrice");o.visible=true;o.characters=data.old;}
  if(data.disc){const d=inst.findOne(n=>n.name==="Discount");d.visible=true;d.findOne(n=>n.name==="DiscountText").characters=data.disc;}
  return inst;
}

