    if(c.name!=="AnnouncementBar"&&c.name!=="Header"&&c.name!=="Newsletter"&&c.name!=="Footer"){
      try{c.layoutSizingHorizontal="HUG";}catch(e){out.push(c.name+" hHUG fail: "+e.message);}
    }
  }
  out.push(c.name+" -> "+Math.round(c.width)+"x"+Math.round(c.height));
}
// also fix nested frames with height 100 inside components
function fixHug(n){
  if("children" in n){
    for(const ch of n.children){
      if(ch.type==="FRAME"&&ch.layoutMode&&ch.layoutMode!=="NONE"&&Math.round(ch.height)===100&&ch.layoutSizingVertical!=="FILL"){
        try{ch.layoutSizingVertical="HUG";}catch(e){}
      }
      fixHug(ch);
    }
  }
}
