function applyStars(inst,score){
  const full=Math.floor(score),half=score-full>=0.5;
  for(let i=1;i<=5;i++){
    const slot=inst.findOne(n=>n.name==="Slot"+i);
    const f=slot.findOne(n=>n.name==="Full"),h=slot.findOne(n=>n.name==="Half");
    if(i<=full){f.visible=true;if(h)h.visible=false;slot.visible=true;}
    else if(i===full+1&&half){f.visible=false;if(h)h.visible=true;slot.visible=true;}
    else{slot.visible=false;}
  }
}
function productCard(data){
  const inst=comps["ProductCard"].createInstance();
  inst.findOne(n=>n.name==="Photo").swapComponent(media[data.photo]);
  inst.findOne(n=>n.name==="Name").characters=data.name;
  applyStars(inst.findOne(n=>n.name==="Stars"),data.score);
  inst.findOne(n=>n.name==="Score").characters=data.score.toFixed(1)+"/5";
  inst.findOne(n=>n.name==="Price").characters=data.price;
  const op=inst.findOne(n=>n.name==="OldPrice");
  if(data.old){op.visible=true;op.characters=data.old;}else op.visible=false;
  const dc=inst.findOne(n=>n.name==="Discount");
  if(data.disc){dc.visible=true;dc.findOne(n=>n.name==="DiscountText").characters=data.disc;}else dc.visible=false;
  return inst;
}
function productRow(items){
  const row=F("ProductRow","HORIZONTAL",20);
  row.counterAxisAlignItems="MIN";
  for(const d of items)row.appendChild(productCard(d));
  return row;
}
