function dump(n,d){
  let s=" ".repeat(d*2)+n.type+" "+n.name+" ("+Math.round(n.width)+"x"+Math.round(n.height)+")"+(n.visible===false?" [h]":"")+(n.type==="TEXT"?" «"+n.characters.slice(0,30)+"»":"")+(n.type==="INSTANCE"?" main="+(n.mainComponent?n.mainComponent.name:"?"):"");
  const out=[s];
  if("children" in n && d<4)for(const c of n.children)out.push(...dump(c,d+1));
  return out;
}
