function txt(chars,{font="Regular",size=16,color=INK,align,spacing,lineHeight,case:cs,width}={}){
  const t=figma.createText();
  t.fontName={family:font==="Archivo"? "Archivo Black":"Plus Jakarta Sans",style:font==="Archivo"?"Regular":font};
  t.fontSize=size;t.characters=chars;t.fills=solid(color);
  if(cs)t.textCase=cs;
  if(spacing)t.letterSpacing={value:spacing,unit:"PIXELS"};
  if(lineHeight)t.lineHeight={value:lineHeight,unit:"PIXELS"};
  if(width){t.textAutoResize="HEIGHT";t.resize(width,t.height);if(align)t.textAlignHorizontal=align;}
  else if(align)t.textAlignHorizontal=align;
  return t;
}
function frame(name,{lm="VERTICAL",gap=0,fill,pad=0,align,justify,radius}={}){
  const f=figma.createFrame();f.name=name;
  if(lm!=="NONE"){f.layoutMode=lm;f.itemSpacing=gap;
    if(pad){f.paddingLeft=f.paddingRight=f.paddingTop=f.paddingBottom=pad;}
    if(align)f.counterAxisAlignItems=align;
    if(justify)f.primaryAxisAlignItems=justify;
  } else f.layoutMode="NONE";
  f.fills=fill?solid(fill):[];
  if(radius!==undefined)f.cornerRadius=radius;
  return f;
}
function setStars(inst,score){
  const full=Math.floor(score),half=(score%1)>=0.5;
  for(let i=1;i<=5;i++){
    const s=inst.findOne(n=>n.name==="Star"+i);
    if(i<=full){const v=s.findOne(n=>n.type==="VECTOR");v.fills=solid(RATING);}
    else if(i===full+1&&half){const ns=s.swapComponent(ICON.star_half);const v=ns.findOne(n=>n.type==="VECTOR");if(v)v.fills=solid(RATING);}
    else{const v=s.findOne(n=>n.type==="VECTOR");v.fills=solid(EMPTY);}
  }
}
function productCard(d){
  const i=C.pc.createInstance();
  const ph=i.findOne(n=>n.name==="Photo");
  ph.swapComponent(PHOTO[d.photo]);
  i.findOne(n=>n.name==="Name").characters=d.name;
  i.findOne(n=>n.name==="Score").characters=d.score.toFixed(1)+"/5";
  setStars(i.findOne(n=>n.name==="Stars"),d.score);
  i.findOne(n=>n.name==="Price").characters="$"+d.price;
  const op=i.findOne(n=>n.name==="OldPrice"),dc=i.findOne(n=>n.name==="Discount");
  if(d.old){op.visible=true;op.characters="$"+d.old;op.textDecoration="STRIKETHROUGH";dc.visible=true;dc.findOne(n=>n.name==="DiscountText").characters=d.disc;}
  else{op.visible=false;dc.visible=false;}
  return i;
}
function productRow(items){
  const row=frame("Cards",{lm:"HORIZONTAL",gap:20});
  for(const d of items){
    const c=productCard(d);row.appendChild(c);
