    const pf=c.findOne(n=>n.name==="PhotoFrame");pf.layoutSizingHorizontal="FILL";
    const ph=c.findOne(n=>n.name==="Photo");ph.layoutSizingHorizontal="FILL";ph.layoutSizingVertical="FILL";
    const nm=c.findOne(n=>n.name==="Name");nm.layoutSizingHorizontal="FILL";
  }
  return row;
}
