function txt(chars,style,size,color,opts){
  const t=figma.createText();
  t.fontName={family:style==="AB"?"Archivo Black":"Plus Jakarta Sans",style:style==="AB"?"Regular":style};
  t.fontSize=size;t.characters=chars;
  t.fills=[{type:"SOLID",color:color||C.ink}];
  if(opts&&opts.lh)t.lineHeight={value:opts.lh,unit:"PIXELS"};
  if(opts&&opts.ls)t.letterSpacing={value:opts.ls,unit:"PIXELS"};
  if(opts&&opts.w){t.textAutoResize="HEIGHT";t.resize(opts.w,t.height);}
  return t;
}
function setStars(inst,score){
  const full=Math.floor(score);
  const half=score%1>=0.5;
  for(let i=1;i<=5;i++){
    const s=inst.findOne(n=>n.name==="Star"+i);
    if(i<=full){/* keep full star */}
    else if(i===full+1&&half){s.swapComponent(starHalf);}
    else{s.visible=false;}
  }
}
function productCard(name,score,price,oldPrice,disc,photoKey){
  const inst=comp["ProductCard"].createInstance();
  inst.findOne(n=>n.name==="ProductName").characters=name;
  const stars=inst.findOne(n=>n.name==="Stars");
  setStars(stars,score);
  inst.findOne(n=>n.name==="Score").characters=score.toFixed(1)+"/5";
  inst.findOne(n=>n.name==="Price").characters="$"+price;
  const op=inst.findOne(n=>n.name==="OldPrice");
  const dg=inst.findOne(n=>n.name==="Discount");
  if(oldPrice){op.characters="$"+oldPrice;op.visible=true;dg.findOne(n=>n.name==="DiscountText").characters="-"+disc+"%";dg.visible=true;}
  else{op.visible=false;dg.visible=false;}
  const ph=inst.findOne(n=>n.name==="Photo");
  const src=photos[photoKey];
  const fill=JSON.parse(JSON.stringify(src.fills[0]));
  fill.scaleMode="FILL";
  ph.fills=[fill];
  return inst;
}

