const INK={r:0,g:0,b:0}, MUTED={r:0.47,g:0.47,b:0.5}, LINE={r:0.9,g:0.9,b:0.91};
const STAR={r:1,g:0.72,b:0.06};
const starFull=await figma.getNodeByIdAsync("4:18");
const starHalf=await figma.getNodeByIdAsync("4:19");

function setStars(inst,score){
  const stars=inst.findOne(n=>n.name==="Stars");
  const full=Math.floor(score), half=score%1>=0.5;
  for(let i=0;i<5;i++){
    const s=stars.children[i];
    s.swapComponent(i<full?starFull:(i===full&&half?starHalf:starFull));
    s.fills=[{type:"SOLID",color:i<full||(i===full&&half)?STAR:{r:0.85,g:0.85,b:0.86}}];
  }
}
function productCard(d){
  const inst=C.ProductCard.createInstance();
  inst.findOne(n=>n.name==="Photo").swapComponent(d.photo);
  inst.findOne(n=>n.name==="ProductName").characters=d.name;
  inst.findOne(n=>n.name==="Score").characters=d.score.toFixed(1)+"/5";
  inst.findOne(n=>n.name==="Price").characters="$"+d.price;
  const old=inst.findOne(n=>n.name==="OldPrice");
  const disc=inst.findOne(n=>n.name==="Discount");
  if(d.old){old.visible=true;old.characters="$"+d.old;disc.visible=true;disc.findOne(n=>n.name==="DiscountText").characters="-"+d.discount+"%";}
  else{old.visible=false;disc.visible=false;}
  setStars(inst,d.score);
  return inst;
}
function productRow(items){
  const row=figma.createFrame();
  row.name="ProductRow";row.layoutMode="HORIZONTAL";row.itemSpacing=20;
  row.fills=[];row.counterAxisSizingMode="AUTO";row.primaryAxisSizingMode="FIXED";
  for(const d of items)row.appendChild(productCard(d));
  row.resize(1240,row.height);
  return row;
}
function sectionTitle(t){
  const txt=figma.createText();
  txt.fontName={family:"Archivo Black",style:"Regular"};
  txt.characters=t;txt.fontSize=32;txt.fills=[{type:"SOLID",color:INK}];
  txt.letterSpacing={value:2,unit:"PIXELS"};
  return txt;
}
function viewAllBtn(){
  const b=figma.createFrame();
  b.name="ViewAll";b.layoutMode="HORIZONTAL";b.itemSpacing=8;
  b.paddingLeft=22;b.paddingRight=22;b.paddingTop=16;b.paddingBottom=16;
  b.cornerRadius=62;b.counterAxisAlignItems="CENTER";
  b.strokes=[{type:"SOLID",color:{r:0.85,g:0.85,b:0.86}}];b.strokeWeight=1;b.fills=[];
  const t=figma.createText();
  t.fontName={family:"Plus Jakarta Sans",style:"Medium"};
  t.characters="View All";t.fontSize=16;t.fills=[{type:"SOLID",color:INK}];
  b.appendChild(t);
  return b;
}
function productSection(title,items){
  const sec=figma.createFrame();
  sec.name=title.replace(/ /g,"_");sec.layoutMode="VERTICAL";sec.itemSpacing=32;
  sec.paddingLeft=100;sec.paddingRight=100;sec.paddingTop=64;sec.paddingBottom=64;
  sec.fills=[];sec.counterAxisSizingMode="AUTO";sec.primaryAxisSizingMode="FIXED";
  const head=figma.createFrame();
  head.name="SectionHead";head.layoutMode="HORIZONTAL";head.primaryAxisSizingMode="FIXED";
  head.counterAxisSizingMode="AUTO";head.primaryAxisAlignItems="SPACE_BETWEEN";head.counterAxisAlignItems="CENTER";head.fills=[];
  head.appendChild(sectionTitle(title));
  head.appendChild(viewAllBtn());
  sec.appendChild(head);
  head.resize(1240,head.height);
  sec.appendChild(productRow(items));
  return sec;
}

